var n=`1006-panang-curry`;var a=`world-1006`;var t=`TH`;var s=`southeast-asia`;var r=4;var o=36;var u={en:`Panang Curry`,ua:`Пананг-карі`};var d={en:`Panang Curry is a dish from Thailand prepared with panang curry paste, coconut cream, beef sirloin, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Пананг-карі, страва кухні країни Таїланд, яку готують із таких продуктів: паста карі пананг, кокосові вершки, яловичий сирлойн, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 5 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 5 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:5,i:[[`panang-curry-paste`,85,`g`],[`coconut-cream`,190,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`beef-sirloin`,600,`g`],[`coconut-milk`,340,`ml`],[`makrut-lime-leaves`,5,`leaf`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,35,`ml`],[`palm-sugar`,25,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`thai-basil`,20,`g`],[`red-bell-pepper`,100,`g`]]}];var l={slug:n,id:a,country:`TH`,region:s,servings:4,minutes:36,title:u,text:d,steps:g};export{t as country,l as default,a as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,u as title};